---RefreshBoardByContent 根据标题和内容刷新提示板
---@param titleText string 标题文字
---@param data table 队伍数据
function CommonTipsBoardFish:RefreshBoardByContent(data, playerName)
	self._playerName = checkString(playerName)
	CfUtils.FillText(self.Text, playerName)

	self:FillTeams(data)
end

function CommonTipsBoardFish:FillTeams(data)
	data = checkTable(data)
	CfUtils.SetActive(self.RecordContentNode, table.count(data) > 0)
	CfUtils.SetActive(self.RecordEmptyNode, table.count(data) <= 0)

	if table.count(data) <= 0 then
		return
	end

	--最多三个
	for i = 1, 3 do
		local t = data[i]
		local go = self.RecordContentNode.transform:Find("node"..i) 
		if  not go then
			go = CfUtils.InstantiateGo(self.Node, self.RecordContentNode)
			go.name = "node"..i
		end
		KTool.SetActive(go, true)

		CfUtils.SetActive(go.transform:Find("Empty"), isNull(t))
		CfUtils.SetActive(go.transform:Find("Content"), not isNull(t))

		if not isNull(t) then
			self:FillTeam(go, t, i)
		end
	end
	--self.TeamsNode.sizeDelta = Vector2(self.TeamsNode.sizeDelta.x, 190 * table.count(data))
end

function CommonTipsBoardFish:FillTeam(go, data, ind)
	if not go then
		return
	end

	local rootGo = go.transform:Find("Content")

	CfUtils.RefeshGoodGo(rootGo.transform:Find("GoodNode"), data.fishId, nil, 0.75, nil, function()
    end)
	CfUtils.SetUISwitchImage(rootGo.transform:Find("TextGrade"), data.rating)
	CfUtils.SetUISwitchImage(rootGo.transform:Find("ImgIcon"), FishingUtils.GetFishRareNameByRare(data.rating) == "S" and 2 or 1)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.fishId)
	CfUtils.FillText(rootGo.transform:Find("TextName"), goodsVo.name)
	CfUtils.FillText(rootGo.transform:Find("TextLength"), (data.length / 100).."CM")
	CfUtils.FillText(rootGo.transform:Find("Score/TextNumber"), data.score)
end

function CommonTipsBoardFish:SetExcludeDialogs(ids)
	self.excludeDialogs = ids
end



return CommonTipsBoardFish